# Generated by subscriber-engine for session 11111111-2222-3333-4444-555555555555. Runs Claude Code interactively in this window and records how it ended.
# Only validated values are substituted into this file; the repository is a quoted literal.
$ErrorActionPreference = 'Continue'
# Claude Code that finds the variables of a parent Claude Code session (the engine was started from one) behaves as that session's child and does not keep
# its own conversation, so a later --resume finds nothing. Forget the variables that name a session; credentials and settings stay.
foreach ($name in @('CLAUDECODE', 'CLAUDE_CODE_CHILD_SESSION', 'CLAUDE_CODE_SESSION_ID', 'CLAUDE_CODE_SESSION_ATTENDED', 'CLAUDE_CODE_ENTRYPOINT', 'CLAUDE_CODE_SSE_PORT', 'CLAUDE_CODE_MESSAGING_SOCKET', 'CLAUDE_PID')) { Remove-Item -LiteralPath ('Env:' + $name) -ErrorAction SilentlyContinue }
$session = 'C:\appmod data\sessions\11111111-2222-3333-4444-555555555555'
$code = $null
try {
    $Host.UI.RawUI.WindowTitle = 'appmod fix 11111111'
    Set-Location -LiteralPath 'C:\work\r&d 100% ^''x (1) é\shop'
    & claude "Read and follow $session\prompt.md" --agent security-fixer --session-id 11111111-2222-3333-4444-555555555555 --name 'appmod fix 11111111' --allowedTools 'Read,Edit,Bash(git *),Bash(node *)' --disallowedTools 'Bash(curl *),Bash(git push *)' --add-dir $session
    $code = $LASTEXITCODE
} finally {
    if ($null -eq $code) { $code = -1 }
    $head = $null
    try { $head = [string](git -C 'C:\work\r&d 100% ^''x (1) é\shop' rev-parse HEAD 2>$null) } catch { }
    if ([string]::IsNullOrWhiteSpace($head)) { $head = $null } else { $head = $head.Trim() }
    $record = [ordered]@{ exitCode = $code; endedAt = (Get-Date).ToUniversalTime().ToString('o'); headEnd = $head } | ConvertTo-Json
    $temp = Join-Path $session 'exit.json.tmp'
    [System.IO.File]::WriteAllText($temp, $record, (New-Object System.Text.UTF8Encoding($false)))
    Move-Item -Force -LiteralPath $temp -Destination (Join-Path $session 'exit.json')
}
exit $code
